#include <vector>
#include <iostream>

void process(const std::vector<int>& c) {
    if (c.empty()) { 
        std::cout << "Container is empty (O(1) check)\n";
    } else {
        std::cout << "Size: " << c.size() << "\n";
    }
}

int main() {
    std::vector<int> v1;
    std::vector<int> v2 = {1, 2, 3};

    process(v1);
    process(v2);
}
